Transformations.Expression:
{
  "Learner": Person.{
    /* Identifier is a multi-source list; the predicate picks the school-assigned
       entry, and the parentheses around the path are required before [0] -- without
       them [0] binds to each match individually and returns them all. */
    "learnerKey": (Identifier[identifierType = "SCHOOL_ASSIGNED_NUMBER"].identifier)[0]
  }
}

{
  "Learner": Person.{
    /* The same learner is reported by several sources, so Name is a list; take the
       first of each part. (Name.firstName)[0] -- parentheses matter, see learnerKey. */
    "displayName": (Name.firstName)[0] & " " & (Name.lastName)[0]
  }
}

{
  "Learner": Person.{
    /* emailAddress is itself an array in LIF and Contact repeats per source, so the
       path yields duplicates; $distinct de-duplicates and the outer [] keeps the
       result an array even when only one address survives. */
    "contactEmails": [$distinct(Contact.Email.emailAddress)]
  }
}

{
  "Learner": Person.{
    /* Identifier.( ... ) maps over each identifier; identifierType is not populated by
       every source, so $exists guards the concatenation instead of producing "100001@". */
    "alternateIds": [$distinct(Identifier.(identifier & "@" & ($exists(identifierType) ? identifierType : "unspecified")))]
  }
}

{
  "Learner": Person.{
    /* LIF stamps provenance on every fragment. Rather than repeating it on every target
       attribute, roll the header's three provenance stamps up into one list. */
    "contributingSystems": [$distinct([Name.informationSourceId, Identifier.informationSourceId, Contact.Email.informationSourceId])]
  }
}

{
  "Enrollment": [Person.CourseLearningExperience.{
    /* LIF has no enrollment-status attribute in this model; derive one from the
       presence of an end date. Test endDate for truthiness rather than
       $exists(endDate): the composed record carries an explicit null when a
       source does not supply the date, and $exists(null) is true. */
    "status": endDate ? "COMPLETED" : "IN_PROGRESS"
  }]
}

{
  "Enrollment": [Person.CourseLearningExperience.{
    /* RefCredentialAward.( ... ) evaluates the concatenation with the referenced award
       as context, so the whole key collapses if the reference is absent -- no "null [null]". */
    "credentialEarned": RefCredentialAward.(name & " [" & identifier & "]")
  }]
}

{
  "Award": [Person.CredentialAward.{
    /* Sources disagree on format: some send "2024-12-15", others a full ISO timestamp.
       Taking the first 10 characters normalizes both to a plain date. */
    "awardedOn": $substring(awardIssueDate, 0, 10)
  }]
}

(
  /* Value mapping. $statusMap must be bound to a variable first: a literal object written
     inline as a $lookup argument is re-read as a grouping expression over the current
     context and silently yields nothing. Unmapped and absent statuses fall back to UNKNOWN. */
  $statusMap := {"Granted": "AWARDED", "Completed": "AWARDED", "InProgress": "IN_PROGRESS", "Revoked": "REVOKED"};
  {
    "Award": [Person.CredentialAward.{
      "awardState": $lookup($statusMap, awardStatus) ? $lookup($statusMap, awardStatus) : "UNKNOWN"
    }]
  }
)

{
  "WorkHistory": [Person.EmploymentLearningExperience.{
    /* Truthiness test rather than $not($exists(endDate)): the composed record
       carries an explicit null when the role has no end date, and $exists(null)
       is true. ($not(endDate) is also wrong -- it drops the key entirely when
       the attribute is absent instead of yielding true.) */
    "isCurrent": endDate ? false : true
  }]
}

{
  "WorkHistory": [Person.EmploymentLearningExperience.{
    /* Some sources send an explicit null rather than omitting the field, and $length(null)
       raises -- so guard on the value itself before measuring it. */
    "roleSummary": RefPosition.description ? ($length(RefPosition.description) > 240 ? $substring(RefPosition.description, 0, 237) & "..." : RefPosition.description) : RefPosition.description
  }]
}

{
  "WorkHistory": [Person.EmploymentLearningExperience.{
    /* Four LIF attributes of one organization reference collapsed into a single string.
       organizationType is array-valued, so $join it -- plain & would stringify the array
       as JSON ("[\"Company\"]"). AssertedByRefOrganization.( ... ) scopes the whole concatenation to the
       reference so the key disappears entirely when the reference is absent. */
    "assertedByOrg": AssertedByRefOrganization.(name & " (" & $join(organizationType, "/") & ") [" & identifier & "@" & identificationSystem & "]")
  }]
}

{
  "WorkHistory": [Person.EmploymentLearningExperience.{
    /* Four LIF attributes of one organization reference collapsed into a single string.
       organizationType is array-valued, so $join it -- plain & would stringify the array
       as JSON ("[\"Company\"]"). OfferedByRefOrganization.( ... ) scopes the whole concatenation to the
       reference so the key disappears entirely when the reference is absent. */
    "trainingProviderOrg": OfferedByRefOrganization.(name & " (" & $join(organizationType, "/") & ") [" & identifier & "@" & identificationSystem & "]")
  }]
}

{
  "WorkHistory": [Person.EmploymentLearningExperience.{
    /* Four LIF attributes of one organization reference collapsed into a single string.
       organizationType is array-valued, so $join it -- plain & would stringify the array
       as JSON ("[\"Company\"]"). ApprovedByRefOrganization.( ... ) scopes the whole concatenation to the
       reference so the key disappears entirely when the reference is absent. */
    "approvingOrg": ApprovedByRefOrganization.(name & " (" & $join(organizationType, "/") & ") [" & identifier & "@" & identificationSystem & "]")
  }]
}

{
  "WorkHistory": [Person.EmploymentLearningExperience.{
    /* LIF references the award from the employment experience; the target embeds it as a
       child object, so the fragment nests an object inside the array element. */
    "RelatedAward": { "title": RefCredentialAward.name }
  }]
}

{
  "Skill": [Person.Proficiency.{
    /* Same null guard as WorkHistory.roleSummary: $length(null) raises, so test the value
       before measuring it. */
    "skillSummary": description ? ($length(description) > 180 ? $substring(description, 0, 177) & "..." : description) : description
  }]
}

{
  "CareerPreference": {
    /* Person.PositionPreferences.{...} yields nothing for a learner with no preferences.
       Nesting it under a literal object keeps the fragment an object either way -- the
       translator drops any fragment that is not a dict, so a bare undefined would be
       logged and discarded instead of simply producing no field. */
    "Mobility": Person.PositionPreferences.{
      "workArrangement": RemoteWork.remoteWorkIndicator ? "REMOTE_OK" : "ONSITE"
    }
  }
}

{
  "CareerPreference": {
    "Mobility": Person.PositionPreferences.{
      /* Two LIF attributes (a flag and a number) become one phrase; $string() is needed
         because & will not concatenate a number. */
      "travelWillingness": Travel.willingToTravelIndicator ? "Up to " & $string(Travel.percentage) & "%" : "None"
    }
  }
}
